import io


class MeteredFile(io.BufferedRandom):
    """Implement using a subclassing model."""

    def __init__(self, *args, **kwargs):
        # counters
        self._read_bytes = 0
        self._read_ops = 0
        self._write_bytes = 0
        self._write_ops = 0

        # Initialize BufferedRandom. Accept either raw file or path-like args.
        try:
            super().__init__(*args, **kwargs)
        except TypeError:
            raw = io.FileIO(*args, **kwargs)
            super().__init__(raw)

    def __enter__(self):
        # Do not delegate to underlying object's __enter__; return the wrapper itself.
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        # Close the buffered file on exit. Do not call underlying __enter__/__exit__.
        # Let BufferedRandom handle cleanup via close().
        self.close()
        return False

    def __iter__(self):
        return self

    def __next__(self):
        # Use the underlying raw stream to avoid double-counting through our read().
        raw = getattr(self, "raw", None)
        if raw is None:
            # Fallback to using superclass readline (may call our read)
            line = super().readline()
        else:
            # raw.readline gives bytes directly from the raw stream
            line = raw.readline()
        if not line:
            raise StopIteration
        # Count this as a read operation
        self._read_ops += 1
        try:
            self._read_bytes += len(line)
        except Exception:
            pass
        return line

    def read(self, size=-1):
        data = super().read(size)
        # Count this read operation and bytes
        self._read_ops += 1
        if data:
            try:
                self._read_bytes += len(data)
            except Exception:
                pass
        return data

    @property
    def read_bytes(self):
        return self._read_bytes

    @property
    def read_ops(self):
        return self._read_ops

    def write(self, b):
        n = super().write(b)
        # Record bytes written; prefer returned count if available.
        try:
            if isinstance(n, int):
                self._write_bytes += n
            else:
                self._write_bytes += len(b)
        except Exception:
            pass
        self._write_ops += 1
        return n

    @property
    def write_bytes(self):
        return self._write_bytes

    @property
    def write_ops(self):
        return self._write_ops


